-- Maintenance PR 2: truck engine fields, maintenance interval templates (read-only reference data),
-- per-truck PM schedules and their status. Follow-up to 20261023000100 / 20261023000200.
-- PROPOSED: Sam reviews, Dakota applies. Idempotent: add column if not exists, create ... if not exists,
-- create or replace, drop ... if exists, seed upsert on seed_key. ASCII only.
--
-- 1. trucks: engine_make, engine_model, engine_year, duty_cycle, mpg, maint_setup_at (added only if missing).
--    make / model / year / vin already exist in prod (only a notice if they do not).
-- 2. service_record_items_type_check gains 'coolant_filter' (drop and re-add, same name).
-- 3. maintenance_interval_templates: 196 rows (189 maker rows + 7 GENERIC rows, is_generic = true).
--    Generated by scripts/maintenance_intervals_seed.py. Notes are our own wording; numbers, source title,
--    source URL and as-of date are kept. Select for any signed-in user; no client writes.
-- 4. pm_schedules: one row per truck and service type. source 'suggested' (template_id set) or 'custom'.
--    Same visibility as service_records (maint_can_see); writes by owner and management only.
--    Last done is not stored: pm_status_for reads the latest service_record_items (baseline visits included).
-- 5. Functions (security definer, search_path = public):
--    pm_engine_choices()            engine list for the setup form
--    pm_fuel_ok(rule, mpg)          does a fuel_rule text match an mpg (immutable helper)
--    pm_suggest(make, model, duty, mpg)  picked template per service type (generic rows if engine unknown)
--    pm_setup_schedules(truck, start_states)  owner / management: insert or refresh suggested rows, custom rows kept
--    pm_status_for(truck, today)    next due by miles or days, whichever first; status
--    pm_due_list(today)             due soon / overdue / due rows across the caller's company trucks

do $$ begin
  if to_regprocedure('public.maint_role(uuid)') is null or to_regprocedure('public.maint_load_ok_for(uuid,uuid)') is null then
    raise exception 'maintenance_schedules: apply 20261023000100 and 20261023000200 first';
  end if;
end $$;

-- 1. trucks.
alter table public.trucks add column if not exists engine_make text;
alter table public.trucks add column if not exists engine_model text;
alter table public.trucks add column if not exists engine_year integer;
alter table public.trucks add column if not exists duty_cycle text;
alter table public.trucks add column if not exists mpg numeric(4,1);
alter table public.trucks add column if not exists maint_setup_at timestamptz;
do $$ declare c text; begin
  if not exists (select 1 from pg_constraint where conrelid = 'public.trucks'::regclass and conname = 'trucks_engine_fields_check') then
    alter table public.trucks add constraint trucks_engine_fields_check check (
      (engine_make is null or length(engine_make) <= 40) and (engine_model is null or length(engine_model) <= 60)
      and (engine_year is null or engine_year between 1980 and 2100)
      and (duty_cycle is null or duty_cycle in ('long_haul', 'short_haul', 'severe', 'unknown'))
      and (mpg is null or mpg between 1 and 20));
  end if;
  foreach c in array array['make', 'model', 'year', 'vin'] loop
    if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'trucks' and column_name = c) then
      raise notice 'maintenance_schedules: trucks.% is missing (expected in prod; not added here)', c;
    end if;
  end loop;
end $$;

-- 2. Item types.
alter table public.service_record_items drop constraint if exists service_record_items_type_check;
alter table public.service_record_items add constraint service_record_items_type_check check (service_type in
  ('oil_filter', 'fuel_filters', 'air_filter', 'coolant', 'coolant_filter', 'def_filter', 'valve_adjustment', 'transmission',
   'differential', 'tires', 'brakes', 'grease', 'dot_annual', 'other'));

-- 3. Templates.
create table if not exists public.maintenance_interval_templates (
  id uuid primary key default gen_random_uuid(),
  seed_key text not null unique,                  -- maker|model|duty|label|seed type|fuel rule
  maker text not null,
  model text not null,
  duty_cycle text not null check (duty_cycle in ('long_haul', 'short_haul', 'severe', 'all')),
  maker_duty_label text,
  seed_service_type text not null,                -- type name in the research sheet
  service_type text not null check (service_type in ('oil_filter', 'fuel_filters', 'air_filter', 'coolant', 'coolant_filter',
    'def_filter', 'valve_adjustment', 'transmission', 'differential')),
  interval_miles integer check (interval_miles is null or interval_miles > 0),
  interval_days integer check (interval_days is null or interval_days > 0),
  interval_hours integer check (interval_hours is null or interval_hours > 0),   -- kept for reference; schedules use miles / days
  fuel_rule text,
  follows_service text,                           -- 'oil_filter': no own interval, done with that service
  source_title text,
  source_url text,
  as_of_date date,
  confidence text check (confidence is null or confidence in ('high', 'medium', 'low')),
  notes text,
  is_generic boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists maintenance_interval_templates_engine_idx on public.maintenance_interval_templates (maker, model, service_type);

insert into public.maintenance_interval_templates (seed_key, maker, model, duty_cycle, maker_duty_label, seed_service_type, service_type,
  interval_miles, interval_days, interval_hours, fuel_rule, follows_service, source_title, source_url, as_of_date, confidence, notes, is_generic)
