on conflict (seed_key) do update set maker = excluded.maker, model = excluded.model, duty_cycle = excluded.duty_cycle,
  maker_duty_label = excluded.maker_duty_label, seed_service_type = excluded.seed_service_type, service_type = excluded.service_type,
  interval_miles = excluded.interval_miles, interval_days = excluded.interval_days, interval_hours = excluded.interval_hours,
  fuel_rule = excluded.fuel_rule, follows_service = excluded.follows_service, source_title = excluded.source_title,
  source_url = excluded.source_url, as_of_date = excluded.as_of_date, confidence = excluded.confidence, notes = excluded.notes,
  is_generic = excluded.is_generic;

alter table public.maintenance_interval_templates enable row level security;
drop policy if exists maintenance_interval_templates_select on public.maintenance_interval_templates;
create policy maintenance_interval_templates_select on public.maintenance_interval_templates for select to authenticated using (true);

-- 4. Schedules.
create table if not exists public.pm_schedules (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,   -- trigger-set from the truck
  truck_id uuid not null references public.trucks(id) on delete cascade,
  service_type text not null check (service_type in ('oil_filter', 'fuel_filters', 'air_filter', 'coolant', 'coolant_filter',
    'def_filter', 'valve_adjustment', 'transmission', 'differential', 'tires', 'brakes', 'grease', 'dot_annual', 'other')),
  interval_miles integer check (interval_miles is null or interval_miles between 1 and 2000000),
  interval_days integer check (interval_days is null or interval_days between 1 and 3650),
  source text not null default 'custom' check (source in ('suggested', 'custom')),
  template_id uuid references public.maintenance_interval_templates(id) on delete restrict,
  start_state text check (start_state is null or start_state in ('due', 'unknown')),  -- shown while there is no record
  created_by uuid default auth.uid() references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint pm_schedules_suggested_template check (source <> 'suggested' or template_id is not null),
  constraint pm_schedules_truck_type_key unique (truck_id, service_type)
);

create or replace function public.pm_schedules_before()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_owner uuid;
begin
  select user_id into v_owner from public.trucks where id = new.truck_id;
  if v_owner is null then raise exception 'truck_not_found' using errcode = '23503'; end if;
  if tg_op = 'UPDATE' and new.truck_id is distinct from old.truck_id then raise exception 'truck_locked' using errcode = '42501'; end if;
  new.owner_id := v_owner;
  if tg_op = 'UPDATE' then
    new.created_by := old.created_by; new.created_at := old.created_at; new.updated_at := now();
    -- A client edit of the numbers turns a suggestion into a custom schedule.
    if (new.interval_miles is distinct from old.interval_miles or new.interval_days is distinct from old.interval_days)
       and new.source = 'suggested' and new.template_id is not distinct from old.template_id and current_setting('pm.refresh', true) is distinct from 'on' then
      new.source := 'custom';
    end if;
  end if;
  return new;
end $$;
drop trigger if exists pm_schedules_before on public.pm_schedules;
create trigger pm_schedules_before before insert or update on public.pm_schedules
  for each row execute function public.pm_schedules_before();

alter table public.pm_schedules enable row level security;
drop policy if exists pm_schedules_select on public.pm_schedules;
create policy pm_schedules_select on public.pm_schedules for select to authenticated
  using (public.maint_can_see(owner_id, truck_id));
drop policy if exists pm_schedules_insert on public.pm_schedules;
create policy pm_schedules_insert on public.pm_schedules for insert to authenticated
  with check (owner_id = public.maint_truck_owner(truck_id) and coalesce(public.maint_role(owner_id) in ('owner', 'management'), false));
drop policy if exists pm_schedules_update on public.pm_schedules;
create policy pm_schedules_update on public.pm_schedules for update to authenticated
  using (coalesce(public.maint_role(owner_id) in ('owner', 'management'), false))
  with check (coalesce(public.maint_role(owner_id) in ('owner', 'management'), false));
drop policy if exists pm_schedules_delete on public.pm_schedules;
create policy pm_schedules_delete on public.pm_schedules for delete to authenticated
  using (coalesce(public.maint_role(owner_id) in ('owner', 'management'), false));

-- 5. Functions.
create or replace function public.pm_engine_choices()
returns table (maker text, model text) language sql stable security definer set search_path = public as $$
  select distinct t.maker, t.model from public.maintenance_interval_templates t
   where not t.is_generic
     and not exists (select 1 from public.maintenance_interval_templates o
                      where o.maker = t.maker and o.model like t.model || ' (%' and not o.is_generic)
   order by 1, 2;
$$;

create or replace function public.pm_fuel_ok(p_rule text, p_mpg numeric)
returns boolean language plpgsql immutable set search_path = public as $$
declare r text; m text[];
begin
  if p_mpg is null or p_rule is null then return true; end if;
  r := lower(trim(split_part(split_part(p_rule, ';', 1), ' or ', 1)));
  m := regexp_match(r, '^([0-9.]+)\s*-\s*([0-9.]+)\s*mpg');
  if m is not null then return p_mpg >= m[1]::numeric and p_mpg < m[2]::numeric + 0.1; end if;
  m := regexp_match(r, '^(>=|<=|>|<)\s*([0-9.]+)\s*mpg');
  if m is null then return true; end if;            -- not an mpg rule (e.g. idle-time based)
  return case m[1] when '>' then p_mpg > m[2]::numeric when '>=' then p_mpg >= m[2]::numeric
                   when '<' then p_mpg < m[2]::numeric else p_mpg <= m[2]::numeric end;
end $$;

-- One template per service type. Engine rows: template model = engine_model, or engine_model is
-- 'template model (...)'. No engine rows -> GENERIC rows. Duty: the truck's duty, then severe, short_haul,
-- long_haul, all ('unknown' starts at severe). Within that duty: rows matching mpg (all rows if mpg is
-- unknown or nothing matches), then the shortest mileage, then the shortest days. Rows with
-- follows_service take that service's picked interval.
create or replace function public.pm_suggest(p_make text, p_model text, p_duty text, p_mpg numeric)
returns table (service_type text, template_id uuid, interval_miles integer, interval_days integer, is_generic boolean)
language sql stable security definer set search_path = public as $$
  with eng as (
    select t.* from public.maintenance_interval_templates t
     where not t.is_generic and p_model is not null
       and (p_make is null or lower(t.maker) = lower(p_make))
       and (t.model = p_model or p_model like t.model || ' (%')
  ), pool as (
    select * from eng
    union all
    select t.* from public.maintenance_interval_templates t where t.is_generic and not exists (select 1 from eng)
  ), duty_rank as (
    select p.*, array_position(array[coalesce(nullif(p_duty, 'unknown'), 'severe'), 'severe', 'short_haul', 'long_haul', 'all'], p.duty_cycle) dr
      from pool p
  ), best_duty as (
    select d.*, min(d.dr) over (partition by d.service_type) mdr,
           bool_or(public.pm_fuel_ok(d.fuel_rule, p_mpg)) over (partition by d.service_type, d.dr) any_fit
      from duty_rank d
  ), picked as (
    select distinct on (b.service_type) b.*
      from best_duty b
     where b.dr = b.mdr and (public.pm_fuel_ok(b.fuel_rule, p_mpg) or not b.any_fit)
     order by b.service_type, (b.interval_miles is null and b.interval_days is null and b.follows_service is null),
              b.interval_miles nulls last, b.interval_days nulls last, b.seed_key
  )
  select p.service_type, p.id,
         coalesce(p.interval_miles, case when p.interval_days is null then f.interval_miles end),
         coalesce(p.interval_days, case when p.interval_miles is null then f.interval_days end),
         p.is_generic
    from picked p left join picked f on f.service_type = p.follows_service;
$$;

-- p_start: jsonb object service_type -> 'due' | 'unknown' (state shown until a record exists).
create or replace function public.pm_setup_schedules(p_truck uuid, p_start jsonb default '{}'::jsonb)
returns integer language plpgsql security definer set search_path = public as $$
declare t record; n integer;
begin
  select * into t from public.trucks where id = p_truck;
  if t.id is null or coalesce(public.maint_role(t.user_id) in ('owner', 'management'), false) is false then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  perform set_config('pm.refresh', 'on', true);
  insert into public.pm_schedules (truck_id, owner_id, service_type, interval_miles, interval_days, source, template_id, start_state)
  select p_truck, t.user_id, s.service_type, s.interval_miles, s.interval_days, 'suggested', s.template_id,
         case when p_start ? s.service_type and p_start->>s.service_type in ('due', 'unknown') then p_start->>s.service_type end
    from public.pm_suggest(t.engine_make, t.engine_model, t.duty_cycle, t.mpg) s
  on conflict (truck_id, service_type) do update
     set interval_miles = excluded.interval_miles, interval_days = excluded.interval_days, template_id = excluded.template_id,
         start_state = coalesce(excluded.start_state, public.pm_schedules.start_state)
   where public.pm_schedules.source = 'suggested';
  get diagnostics n = row_count;
  perform set_config('pm.refresh', 'off', true);
  return n;
end $$;

create or replace function public.pm_la_today()
returns date language sql stable set search_path = public as $$ select (now() at time zone 'America/Los_Angeles')::date $$;

create or replace function public.pm_status_for(p_truck uuid, p_today date default null)
returns table (schedule_id uuid, service_type text, interval_miles integer, interval_days integer, source text, template_id uuid,
  source_title text, as_of_date date, is_generic boolean, template_notes text,
  last_done_date date, last_done_odometer integer, next_due_odometer integer, next_due_date date,
  miles_left integer, days_left integer, status text)
language sql stable security definer set search_path = public as $$
  with tr as (
    select t.id, t.user_id, t.odometer from public.trucks t where t.id = p_truck and public.maint_can_see(t.user_id, t.id)
  ), s as (
    select ps.*, tr.odometer truck_odo, coalesce(p_today, public.pm_la_today()) today,
           (select r.service_date from public.service_record_items i join public.service_records r on r.id = i.service_record_id
             where r.truck_id = ps.truck_id and i.service_type = ps.service_type order by r.service_date desc, r.odometer desc nulls last limit 1) ld,
           (select r.odometer from public.service_record_items i join public.service_records r on r.id = i.service_record_id
             where r.truck_id = ps.truck_id and i.service_type = ps.service_type and r.odometer is not null
             order by r.service_date desc, r.odometer desc limit 1) lo
      from public.pm_schedules ps join tr on tr.id = ps.truck_id
  ), d as (
    select s.*, s.lo + s.interval_miles ndo, s.ld + s.interval_days ndd,
           s.lo + s.interval_miles - s.truck_odo ml, (s.ld + s.interval_days) - s.today dl
      from s
  )
  select d.id, d.service_type, d.interval_miles, d.interval_days, d.source, d.template_id,
         m.source_title, m.as_of_date, coalesce(m.is_generic, false), m.notes,
         d.ld, d.lo, d.ndo, d.ndd, d.ml, d.dl,
         case
           when d.ld is null then coalesce(d.start_state, 'unknown')
           when d.interval_miles is null and d.interval_days is null then 'unknown'
           when d.ml < 0 or d.dl < 0 then 'overdue'
           when d.ml <= ceil(d.interval_miles * 0.1) or d.dl <= 14 then 'due_soon'
           when d.ml is null and d.dl is null then 'unknown'   -- miles-only interval but no odometer reading
           else 'ok' end
    from d left join public.maintenance_interval_templates m on m.id = d.template_id
   order by d.service_type;
$$;

create or replace function public.pm_due_list(p_today date default null)
returns table (truck_id uuid, unit_number text, service_type text, status text, miles_left integer, days_left integer,
  next_due_odometer integer, next_due_date date)
language sql stable security definer set search_path = public as $$
  select t.id, t.unit_number, s.service_type, s.status, s.miles_left, s.days_left, s.next_due_odometer, s.next_due_date
    from public.trucks t cross join lateral public.pm_status_for(t.id, p_today) s
   where public.maint_role(t.user_id) is not null and public.maint_can_see(t.user_id, t.id)
     and s.status in ('overdue', 'due', 'due_soon')
   order by case s.status when 'overdue' then 1 when 'due' then 2 else 3 end, s.miles_left nulls last, s.days_left nulls last;
$$;

-- 6. Grants: authenticated only. owner_id / created_by / timestamps are trigger-set.
revoke all on public.maintenance_interval_templates, public.pm_schedules from public;
do $$ declare f text; begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on public.maintenance_interval_templates, public.pm_schedules from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on public.maintenance_interval_templates from authenticated';
    execute 'grant select on public.maintenance_interval_templates to authenticated';
    execute 'grant select, delete on public.pm_schedules to authenticated';
    execute 'grant insert (id, truck_id, owner_id, service_type, interval_miles, interval_days, source, template_id, start_state) on public.pm_schedules to authenticated';
    execute 'grant update (interval_miles, interval_days, source, template_id, start_state) on public.pm_schedules to authenticated';
    execute 'grant update (engine_make, engine_model, engine_year, duty_cycle, mpg, maint_setup_at) on public.trucks to authenticated';
  end if;
  foreach f in array array['pm_engine_choices()', 'pm_fuel_ok(text,numeric)', 'pm_suggest(text,text,text,numeric)', 'pm_setup_schedules(uuid,jsonb)',
      'pm_la_today()', 'pm_status_for(uuid,date)', 'pm_due_list(date)'] loop
    execute format('revoke all on function public.%s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function public.%s from anon', f); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('grant execute on function public.%s to authenticated', f); end if;
  end loop;
  execute 'revoke all on function public.pm_schedules_before() from public';
end $$;
